function maxCompressedStringLength(s) {
  const n = s.length;
  const dp = new Array(n + 1).fill(0);

  for (let i = 1; i <= n; i++) {
    dp[i] = dp[i - 1] + 1;

    for (let j = 0; j < i; j++) {
      const sub = s.substring(j, i);
      const count = getRepeatCount(sub);
      if (count > 1) {
        const compressedLength = sub.length - (sub.length - 1) + String(count).length;
        dp[i] = Math.min(dp[i], dp[j] + compressedLength);
      }
    }
  }

  return dp[n];
}

function getRepeatCount(s) {
  const repeat = s.match(/^(.)\1*/);
  if (!repeat) return 1;
  const match = repeat[0];
  const repeatCount = Math.floor(match.length / repeat[1].length);
  return repeatCount;
}
